+/**
+ * Tracks whether an embeddable's iframe has gone "stale" (needs remount)
+ * due to props that cannot be updated in-place (e.g. sandbox).
+ */
+const staleIframes = new Map<string, true>();
+
+export const markIframeStale = (id: string) => {
+  staleIframes.set(id, true);
+};
+
+export const consumeIframeStale = (id: string) => {
+  if (staleIframes.has(id)) {
+    staleIframes.delete(id);
+    return true;
+  }
+  return false;
+};
