+const SAFE_URL_PATTERN = /^(?:(?:https?|mailto|ftp|tel):|[^&:/?#]*(?:[/?#]|$))/i
+
+// Compatible with browsers that lack URL constructor support for relative URLs
+// or non-standard schemes; falls back to a conservative regex allow-list.
+export const urlIsSafe = (urlString) => {
+  if (!urlString) return false
+  const trimmed = ("" + urlString).trim()
+  if (!trimmed) return false
+
+  try {
+    // Resolve against a fixed base so relative paths are accepted while
+    // still exposing the true protocol for absolute URLs.
+    const parsed = new URL(trimmed, "https://example.com")
+    const protocol = parsed.protocol.toLowerCase()
+    return protocol === "http:" ||
+           protocol === "https:" ||
+           protocol === "mailto:" ||
+           protocol === "ftp:" ||
+           protocol === "tel:" ||
+           protocol === "http:" // keep relative / same-document
+  } catch {
+    // URL constructor rejected the string – apply the regex allow-list
+    return SAFE_URL_PATTERN.test(trimmed)
+  }
+}
+
+export const sanitizeURL = (urlString) => {
+  return urlIsSafe(urlString) ? urlString.trim() : null
+}
