 /* @flow */

 import type {Hash as CryptoHash} from 'crypto';

 const crypto = require('crypto');
 const fs = require('fs');
 const stream = require('stream');

+/**
+ * Hash the contents of an open file descriptor.
+ * The fd position is not relied upon; reading starts at offset 0.
+ * The caller retains ownership of the fd (it is not closed here).
+ */
+export function hashFd(fd: number, algorithm: string = 'sha1'): Promise<string> {
+  return new Promise((resolve, reject) => {
+    const hash = crypto.createHash(algorithm);
+    const input = fs.createReadStream('', {
+      fd,
+      start: 0,
+      autoClose: false,
+    });
+    input.on('data', data => hash.update(data));
+    input.on('end', () => resolve(hash.digest('hex')));
+    input.on('error', err => reject(err));
+  });
+}
+
 export function hashFile(file: string, algorithm: string = 'sha1'): Promise<string> {
   return new Promise((resolve, reject) => {
     const hash = crypto.createHash(algorithm);
     const input = fs.createReadStream(file);
     input.on('data', data => hash.update(data));
     input.on('end', () => resolve(hash.digest('hex')));
     input.on('error', err => reject(err));
   });
 }

 export function hashStream(input: stream.Readable, algorithm: string = 'sha1'): Promise<string> {
   return new Promise((resolve, reject) => {
     const hash = crypto.createHash(algorithm);
     input.on('data', data => hash.update(data));
     input.on('end', () => resolve(hash.digest('hex')));
     input.on('error', err => reject(err));
   });
 }

